const raw = ($('Webhook /xhs/feedback').item.json.body?.data || '').trim();
const parts = raw.split(':');
if (parts.length < 3 || parts[0] !== 'xhs') {
  return [{ json: { error: 'invalid callback data', raw }}];
}
const draft_id = parts[1];
const action = parts[2];
const VALID_ACTIONS = ['love','like','discard','save_seed'];
if (!VALID_ACTIONS.includes(action)) {
  return [{ json: { error: 'invalid action', action, raw }}];
}

const fs = require('fs');
const draftDir = `/home/david/xhs-drafts/${draft_id}`;
const notePath = `${draftDir}/note.md`;

let noteContent = '';
let title = '';
let body = '';
let tags = [];
let category = 'unknown';
try {
  noteContent = fs.readFileSync(notePath, 'utf8');
  // Parse title (# ...)
  const titleMatch = noteContent.match(/^#\s+(.+)$/m);
  if (titleMatch) title = titleMatch[1].trim();
  // Parse category from footer: _生成基于 <cat> 类目_
  const catMatch = noteContent.match(/生成基于\s+(\S+)\s+类目/);
  if (catMatch) category = catMatch[1];
  // Body = between title and tags
  // Split content into lines; body is between title line and tag line
  const lines = noteContent.split('\n');
  const bodyLines = [];
  let inBody = false;
  for (const line of lines) {
    if (line.startsWith('# ')) { inBody = true; continue; }
    if (line.trim().startsWith('#') && line.includes(' #')) break; // tag line
    if (line.trim() === '---') break;
    if (inBody) bodyLines.push(line);
  }
  body = bodyLines.join('\n').trim();
  // Parse tag line
  const tagLineMatch = noteContent.match(/^(#[^\n#][^\n]*(?:\s#[^\n]*)+)$/m);
  if (tagLineMatch) {
    tags = tagLineMatch[1].split(/\s+/).map(t => t.replace(/^#/, '').trim()).filter(Boolean);
  }
} catch (e) {
  return [{ json: { error: 'draft not found', draft_id, notePath }}];
}

return [{ json: { draft_id, action, category, title, body, tags, note_path: notePath, draft_dir: draftDir }}];

const fs = require('fs');
const p = $input.first().json;

// slug from title (first 30 chars, safe chars)
const slug = (p.title || 'untitled').replace(/[^\w\u4e00-\u9fa5]/g,'_').substring(0,30);
const seedPath = `/home/david/xhs-corpus/seed_notes/${p.draft_id}-${slug}.md`;

// YAML frontmatter
const fm = `---\ncategory: ${p.category}\nadded_at: ${new Date().toISOString()}\nsource: user-saved-from-generated\ninitial_score: 0.7\ndraft_id: ${p.draft_id}\ntags: [${(p.tags || []).map(t => `"${t}"`).join(', ')}]\n---\n\n`;

// Compose seed content: title + body (no tags footer, no metadata footer)
const seedContent = fm + `# ${p.title}\n\n${p.body}\n`;

fs.writeFileSync(seedPath, seedContent);

// Also log score = +0.5 for saved-as-seed
const scoreEntry = {
  draft_id: p.draft_id,
  category: p.category,
  action: 'save_seed',
  delta: 0.5,
  ts: new Date().toISOString()
};
fs.appendFileSync('/home/david/xhs-corpus/scores.jsonl', JSON.stringify(scoreEntry) + '\n');

return [{ json: { ...p, seed_path: seedPath, saved: true }}];

const fs = require('fs');
const p = $input.first().json;

const DELTA_MAP = {
  'love': 0.4,
  'like': 0.1,
  'discard': -0.3
};
const delta = DELTA_MAP[p.action] ?? 0;

const scoreEntry = {
  draft_id: p.draft_id,
  category: p.category,
  action: p.action,
  delta,
  ts: new Date().toISOString()
};
fs.appendFileSync('/home/david/xhs-corpus/scores.jsonl', JSON.stringify(scoreEntry) + '\n');

return [{ json: { ...p, delta, saved: true }}];
